<?php
namespace App\Http\Controllers\Admin; use App\Domain\Installation\WebsiteSettings; use App\Domain\Statistics\{StatisticDependencyInspector,StatisticManager,StatisticRegistry,StatisticViewData}; use App\Http\Controllers\Controller; use App\Http\Requests\Statistics\SaveStatisticRequest; use App\Models\Statistic; use Illuminate\Contracts\View\View; use Illuminate\Http\{RedirectResponse,Request,Response}; use Illuminate\Support\Carbon; use Illuminate\Validation\Rule; class StatisticController extends Controller { public function index(Request $r):View{$f=$r->validate(['search'=>['nullable','string','max:160'],'group'=>['nullable',Rule::in(StatisticRegistry::GROUPS)],'status'=>['nullable',Rule::in(['draft','published','scheduled','archived'])],'featured'=>['nullable','in:0,1'],'archived'=>['nullable','in:with,only,without']]);$q=Statistic::when($f['search']??null,fn($q,$v)=>$q->where(fn($q)=>$q->where('label','like',"%$v%")->orWhere('value','like',"%$v%")))->when($f['group']??null,fn($q,$v)=>$q->where('statistic_group',$v))->when($f['status']??null,fn($q,$v)=>$q->where('status',$v))->when(isset($f['featured']),fn($q)=>$q->where('is_featured',(bool)$f['featured']));if(($f['archived']??'without')==='only')$q->whereNotNull('archived_at');elseif(($f['archived']??'without')==='without')$q->whereNull('archived_at');return view('admin.statistics.index',['statistics'=>$q->orderBy('display_order')->paginate(20)->withQueryString()]);} public function create():View{return $this->editor(new Statistic);} public function store(SaveStatisticRequest $r,StatisticManager $m):RedirectResponse{return redirect()->route('admin.statistics.edit',$m->save($r->validated(),null,$r->user()->id));} public function edit(Statistic $statistic):View{return $this->editor($statistic);} public function update(SaveStatisticRequest $r,Statistic $statistic,StatisticManager $m):RedirectResponse{$m->save($r->validated(),$statistic,$r->user()->id);return back();} private function editor(Statistic $item):View{return view('admin.statistics.editor',['statistic'=>$item,'groups'=>StatisticRegistry::GROUPS,'dependencies'=>$item->exists?app(StatisticDependencyInspector::class)->inspect($item):null]);} public function publish(Statistic $statistic,StatisticManager $m):RedirectResponse{$m->publish($statistic);return back();} public function schedule(Request $r,Statistic $statistic,StatisticManager $m):RedirectResponse{$v=$r->validate(['scheduled_for'=>['required','date']]);$tz=app(WebsiteSettings::class)->current()?->timezone?:'UTC';$m->schedule($statistic,Carbon::parse($v['scheduled_for'],$tz)->utc()->toDateTimeString());return back();} public function unpublish(Statistic $statistic,StatisticManager $m):RedirectResponse{$m->unpublish($statistic);return back();} public function archive(Statistic $statistic,StatisticManager $m):RedirectResponse{$m->archive($statistic);return back();} public function restore(Statistic $statistic,StatisticManager $m):RedirectResponse{$m->restore($statistic);return back();} public function duplicate(Request $r,Statistic $statistic,StatisticManager $m):RedirectResponse{return redirect()->route('admin.statistics.edit',$m->duplicate($statistic,$r->user()->id));} public function move(Statistic $statistic,string $direction,StatisticManager $m):RedirectResponse{$m->move($statistic,$direction);return back();} public function preview(Statistic $statistic,StatisticViewData $d):Response{return response()->view('statistics.preview',['statistic'=>$d->preview($statistic)])->header('Cache-Control','no-store, private, max-age=0')->header('X-Robots-Tag','noindex, nofollow');} }
